"""A deliberately broken workflow, so `civet demo` shows value in one command.

Every line here is a real pattern taken from public post-mortems; the file is
written to a temp/target directory and never into the caller's repository.
"""

from __future__ import annotations

import os

DEMO_WORKFLOW = """\
# civet demo — every finding below is intentional.
# Generated by `civet demo`; safe to delete.

name: CI

on:
  push:
  pull_request_target:
  issue_comment:

jobs:
  build:
    runs-on: self-hosted
    steps:
      - uses: actions/checkout@v4
        with:
          ref: ${{ github.event.pull_request.head.sha }}
          persist-credentials: true

      - name: Greet the contributor
        run: echo "building ${{ github.event.pull_request.title }}"

      - name: Install toolchain
        run: curl -fsSL https://cdn.example-toolchain.io/install.sh | bash

      - name: Run helper
        run: npx some-helper-cli --go

      - name: Record output
        run: echo "result=$RESULT" >> $GITHUB_ENV

      - name: Export
        run: echo "::set-output name=sha::$(git rev-parse HEAD)"

      - name: Upload
        uses: actions/upload-artifact@v4
        with:
          path: dist/

      - name: Cache
        uses: actions/cache@v4
        with:
          path: ~/.cache
          key: deps-${{ github.event.pull_request.head.sha }}

      - name: Publish
        uses: third-party/publish-action@main
        with:
          token: ${{ secrets.GITHUB_TOKEN }}
          notes: ${{ github.event.issue.body }}

      - name: Upload scan results
        # No permissions: block anywhere in this workflow, so the uploader has
        # no security-events scope and the API call is rejected at run time.
        uses: github/codeql-action/upload-sarif@v3
        with:
          sarif_file: results.sarif

      - name: Audit
        run: npm audit || true
        continue-on-error: true

  deploy:
    runs-on: ubuntu-latest
    permissions: write-all
    if: github.event.issue.title == 'ship it'
    env:
      REGISTRY_TOKEN: ${{ secrets.REGISTRY_TOKEN }}
    steps:
      - name: Push image
        run: |
          echo "$REGISTRY_TOKEN" | docker login -u bot --password-stdin
          IMAGE=$(echo "${{ github.head_ref }}" | tr -d '\\n')
          eval "docker push registry.example.com/app:$IMAGE"
"""


DEMO_WORKFLOW_2 = """\
# civet demo (part 2) — advanced trigger and supply-chain patterns.

name: Release

on:
  workflow_run:
    workflows: ["CI"]
  pull_request_target:

jobs:
  release:
    runs-on: ubuntu-latest
    container: node:latest
    if: ${{ secrets.RELEASE_ENABLED == 'true' }}
    steps:
      - name: Comment on the PR
        if: github.event.issue.title == 'ship'
        uses: actions/github-script@v7
        with:
          script: console.log("${{ github.event.issue.body }}")

      - name: Publish with shared token
        uses: third-party/publisher@v2
        with:
          token: ${{ secrets.GITHUB_TOKEN }}

      - name: Notify channel
        uses: third-party/notifier@v1
        with:
          api_key: ${{ secrets.SLACK_WEBHOOK }}

      - name: Show token
        run: |
          echo "token=${{ secrets.GITHUB_TOKEN }}" >> "$GITHUB_STEP_SUMMARY"

  downstream:
    uses: some-org/shared-workflows/.github/workflows/deploy.yml@main
    secrets: inherit
"""


def write_demo(target_dir: str) -> str:
    """Write both demo workflows into ``target_dir/.github/workflows``.

    The subdirectory matters: GitHub only loads workflows from there, and
    civet's discovery enforces the same rule rather than guessing from
    ``*.yml`` anywhere in the tree.
    """
    out_dir = os.path.join(target_dir, ".github", "workflows")
    os.makedirs(out_dir, exist_ok=True)
    for name, body in (
        ("civet-demo.yml", DEMO_WORKFLOW),
        ("civet-demo-advanced.yml", DEMO_WORKFLOW_2),
    ):
        with open(os.path.join(out_dir, name), "w", encoding="utf-8", newline="\n") as fh:
            fh.write(body)
    return out_dir
